import {EXO_INSTRUMENT,EXO_PRESETS,EXO_WAVES,exoSettings} from './exo.js?v=0.13.0';
const view={search:'',category:'All',favorites:false,advanced:false};
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}};
const favoriteKey='warlike.exo.favorites.v1',userKey='warlike.exo.user.v1';
function patches(){const raw=read(userKey,[]),users=(Array.isArray(raw)?raw:[]).slice(0,64).filter(p=>p&&typeof p.name==='string'&&p.values).map(p=>({id:p.id,name:p.name.slice(0,50),category:'User',mood:'Personnel',values:exoSettings(p.values)}));return [...EXO_PRESETS.map((p,i)=>({...p,id:'factory-'+i,values:exoSettings(p.values)})),...users];}
export function mountExoBrowser({panel,track,engine,checkpoint,changed,toast,paramHTML,esc}){
 panel.classList.add('exo-instrument');const old=panel.querySelector('.plugin-window-params');old?.remove();panel.querySelector('.plugin-mouse-guide')?.remove();
 const root=document.createElement('section');root.className='exo-browser-panel';root.innerHTML=`<div class="exo-hero"><div><span>WARLIKE / EXO COLLECTION</span><h2>EXO<span>DUAL LAYER SYNTH</span></h2><p>32 factory sounds · VA / FM · stereo unison</p></div><svg viewBox="0 0 240 65" aria-hidden="true"><path d="M0 33Q15 3 30 33T60 33T90 33T120 33T150 33T180 33T210 33T240 33"/><path d="M0 33Q10 60 20 33T40 33T60 33T80 33T100 33T120 33T140 33T160 33T180 33T200 33T220 33T240 33"/></svg></div><div class="exo-search-row"><input id="exoSearch" aria-label="Rechercher un son EXO" placeholder="Rechercher un son, une humeur…" value="${esc(view.search)}"><button id="exoFavorites" aria-pressed="${view.favorites}">★ Favoris</button><button id="exoAudition">▶ Accord / arp</button><button id="exoStop">■ Stop</button></div><div class="exo-library"><nav class="exo-categories" aria-label="Catégories EXO"></nav><div><div id="exoResults" class="exo-result-count"></div><div class="exo-patches" id="exoPatches"></div></div></div><div class="exo-user-row"><input id="exoUserName" aria-label="Nom de mon preset EXO" placeholder="Nom de mon son…" maxlength="50"><button id="exoSaveUser">Sauver mon son</button><small>64 sons personnels maximum · sur cet appareil</small></div><div class="exo-keys" aria-label="Clavier de préécoute EXO">${Array.from({length:25},(_,i)=>{const midi=48+i;return `<button data-exo-note="${midi}" class="${[1,3,6,8,10].includes(midi%12)?'black':''}" aria-label="Jouer EXO note ${midi}">${midi%12===0?'C'+(midi/12-1):''}</button>`;}).join('')}</div><div class="exo-control-group"><h3>MACROS / TONE</h3><div class="plugin-window-params">${EXO_INSTRUMENT.controls.slice(0,8).map(c=>paramHTML(c,track.instrument[c.key],'instrument')).join('')}</div></div><details class="exo-advanced" ${view.advanced?'open':''}><summary>LAYERS · ENVELOPE · ARPEGGIATOR</summary><div class="exo-layer-choices">${['A','B'].map(layer=>`<label>Layer ${layer}<select data-exo-control="wave${layer}" aria-label="Forme couche ${layer}">${EXO_WAVES.map((name,i)=>`<option value="${i}" ${Math.round(track.instrument['wave'+layer])===i?'selected':''}>${name}</option>`).join('')}</select></label>`).join('')}<label>Arpeggiator<select data-exo-control="arpMode" aria-label="Mode arpégiateur EXO">${['Off','Up','Down','Up/Down','Chord'].map((name,i)=>`<option value="${i}" ${Math.round(track.instrument.arpMode)===i?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="plugin-window-params">${EXO_INSTRUMENT.controls.slice(8).filter(c=>!['waveA','waveB','arpMode'].includes(c.key)).map(c=>paramHTML(c,track.instrument[c.key],'instrument')).join('')}</div><p>L’arpégiateur utilise les notes tenues du pattern en PAT, en SONG et à l’export. Un pas vaut une double croche. Les touches ci-dessus écoutent une note ; « Accord / arp » préécoute une progression.</p></details>`;
 panel.querySelector('.plugin-window-meta').insertAdjacentElement('afterend',root);
 root.querySelector('.exo-advanced').ontoggle=e=>view.advanced=e.target.open;
 const render=()=>{const all=patches(),rawFavorites=read(favoriteKey,[]),favorites=new Set(Array.isArray(rawFavorites)?rawFavorites:[]),categories=['All',...new Set(all.map(p=>p.category))];root.querySelector('.exo-categories').innerHTML=categories.map(category=>`<button data-exo-category="${esc(category)}" aria-pressed="${view.category===category}"><span>${category==='All'?'Tous les sons':category}</span><small>${category==='All'?all.length:all.filter(p=>p.category===category).length}</small></button>`).join('');const normal=s=>s.toLocaleLowerCase().normalize('NFD').replace(/\p{M}/gu,''),search=normal(view.search),shown=all.filter(p=>(view.category==='All'||p.category===view.category)&&(!view.favorites||favorites.has(p.id))&&normal(p.name+' '+p.category+' '+p.mood).includes(search));root.querySelector('#exoResults').textContent=shown.length+' son(s) · Factory 32 / User '+(all.length-32);root.querySelector('#exoFavorites').setAttribute('aria-pressed',String(view.favorites));root.querySelector('#exoPatches').innerHTML=shown.map(p=>{const selected=EXO_INSTRUMENT.controls.every(c=>Math.abs(track.instrument[c.key]-p.values[c.key])<1e-8);return `<article class="exo-patch ${selected?'chosen':''}"><button data-exo-load="${esc(p.id)}" aria-label="Charger ${esc(p.name)}"><strong>${esc(p.name)}</strong><span>${p.category} · ${esc(p.mood)}</span></button><button data-exo-preview="${esc(p.id)}" aria-label="Écouter ${esc(p.name)}">▶</button><button data-exo-favorite="${esc(p.id)}" aria-label="Favori ${esc(p.name)}" aria-pressed="${favorites.has(p.id)}">${favorites.has(p.id)?'★':'☆'}</button>${p.category==='User'?`<button data-exo-delete="${esc(p.id)}" aria-label="Retirer ${esc(p.name)}">×</button>`:''}</article>`;}).join('')||'<p class="exo-no-results">Aucun son dans ce filtre.</p>';};
 root.querySelector('#exoSearch').oninput=e=>{view.search=e.target.value;render();};root.querySelector('#exoFavorites').onclick=()=>{view.favorites=!view.favorites;render();};
 root.querySelector('#exoAudition').onclick=()=>engine.previewPreset('exo',track.instrument).catch(e=>toast(e.message));root.querySelector('#exoStop').onclick=()=>engine.stopPreview();
 root.querySelector('#exoSaveUser').onclick=()=>{const name=root.querySelector('#exoUserName').value.trim();if(!name){toast('Donne un nom à ce son.');return;}const users=patches().filter(p=>p.category==='User');if(users.length>=64){toast('Retire un son personnel avant d’en ajouter un.');return;}users.push({id:'user-'+Date.now().toString(36),name,category:'User',values:exoSettings(track.instrument)});if(!write(userKey,users)){toast('Stockage indisponible : exporte le rack pour conserver ce son.');return;}view.category='User';view.search='';root.querySelector('#exoSearch').value='';view.favorites=false;render();toast('Son EXO conservé sur cet appareil.');};
 root.addEventListener('change',e=>{const key=e.target.dataset.exoControl;if(!key)return;checkpoint();track.instrument[key]=Number(e.target.value);changed(true);});
 root.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;const {exoCategory,exoLoad,exoPreview,exoFavorite,exoDelete,exoNote}=button.dataset;if(exoCategory){view.category=exoCategory;render();}else if(exoLoad){const p=patches().find(p=>p.id===exoLoad);if(p){checkpoint();Object.assign(track.instrument,p.values);changed(true);toast(p.name+' chargé.');}}else if(exoPreview){const p=patches().find(p=>p.id===exoPreview);if(p)engine.previewPreset('exo',p.values).catch(e=>toast(e.message));}else if(exoFavorite){const current=read(favoriteKey,[]),favorites=new Set(Array.isArray(current)?current:[]);favorites.has(exoFavorite)?favorites.delete(exoFavorite):favorites.add(exoFavorite);write(favoriteKey,[...favorites]);render();}else if(exoDelete){const removed=patches().find(p=>p.id===exoDelete);write(userKey,patches().filter(p=>p.category==='User'&&p.id!==exoDelete));render();toast(removed.name+' retiré de la banque personnelle.');}else if(exoNote)engine.preview('exo',Number(exoNote),track.id).catch(e=>toast(e.message));});render();
}
